// Generate conformance/trust-config/vectors.json. Deterministic: every key is
// a SYNTHETIC canary Ed25519 key derived from a public label, so the vectors
// can be regenerated byte-for-byte and no private key is stored anywhere.
// Run: node conformance/trust-config/generate.mjs [--check]
import crypto from "node:crypto";
import fs from "node:fs";
import path from "node:path";
import { fileURLToPath } from "node:url";
import { signTrustConfig } from "../../runtime/trustConfig.js";
import { consumptionKey } from "../../runtime/consumptionStore.js";

const here = path.dirname(fileURLToPath(import.meta.url));
const PKCS8_ED25519_PREFIX = Buffer.from("302e020100300506032b657004220420", "hex");

function canary(label) {
  const seed = crypto.createHash("sha256").update(`aml-trust-conformance-canary/1\0${label}`).digest();
  const privateKey = crypto.createPrivateKey({ key: Buffer.concat([PKCS8_ED25519_PREFIX, seed]), format: "der", type: "pkcs8" });
  const publicKey = crypto.createPublicKey(privateKey);
  return {
    pem: privateKey.export({ type: "pkcs8", format: "pem" }).toString(),
    publicPem: publicKey.export({ type: "spki", format: "pem" }).toString(),
    sha256: crypto.createHash("sha256").update(publicKey.export({ type: "spki", format: "der" })).digest("hex")
  };
}

const R = [0, 1, 2].map(i => canary(`root-${i}`));
const N = [0, 1, 2].map(i => canary(`new-root-${i}`));
const OUT = canary("outsider");
const K = canary("receipt-signer");
const P = canary("policy-signer");
const ISSUED = "2026-01-01T00:00:00Z";
const EXPIRES = "2099-01-01T00:00:00Z";
const POLICY = "a".repeat(64);

const anchor = (roots = R, threshold = 2) => ({ threshold, keyids: roots.map(r => r.sha256) });
const body = (over = {}) => ({
  type: "aml-trust-config/1", version: 1, issued_at: ISSUED, expires_at: EXPIRES,
  root: anchor(), trusted_keys: [{ keyid: K.sha256, roles: ["receipt"] }, { keyid: P.sha256, roles: ["policy-pack"] }],
  revoked_keys: [], policy_sha256: POLICY, registry_sha256: null, profile_sha256: null, require_single_use: false, ...over
});
const sign = (b, keys = [R[0], R[1]]) => signTrustConfig(b, keys.map(k => k.pem));
// Sign bytes the JS validator would refuse (for malformed-body cases).
const rawSign = (b, keys = [R[0], R[1]]) => {
  const canonical = s => Array.isArray(s) ? `[${s.map(canonical).join(",")}]`
    : s && typeof s === "object" ? `{${Object.keys(s).sort().map(k => `${JSON.stringify(k)}:${canonical(s[k])}`).join(",")}}` : JSON.stringify(s);
  const message = Buffer.from(canonical(b));
  return { signed: b, signatures: keys.map(k => ({ keyid: k.sha256, public_key_pem: k.publicPem,
    signature_base64: crypto.sign(null, message, crypto.createPrivateKey(k.pem)).toString("base64") })) };
};
const ok = (extra = {}) => ({ trusted: true, reasons: [], ...extra });
const deny = (...reasons) => ({ trusted: false, reasons });
const malformed = deny("envelope_well_formed", "root_threshold_met", "new_root_threshold_met", "not_rolled_back",
  "no_version_fork", "caller_time_absent", "trusted_time", "issued_not_in_future", "not_expired", "state_persisted");
const step = (envelope, expect, extra = {}) => ({ envelope, expect, ...extra });

const v1 = sign(body());
const v2 = sign(body({ version: 2 }));
const v3 = sign(body({ version: 3 }));
// A fixed P-256 public key (public material only; it signs nothing here):
// Ed25519 is the only accepted key type.
const P256_PEM = "-----BEGIN PUBLIC KEY-----\nMFkwEwYHKoZIzj0CAQYIKoZIzj0DAQcDQgAEptSrR5H5yyPYGa3At3DVbvUTeygq\nT2KL0ekxwMB+8mk3FwJhs0ipfSiV6YhDf8sbCo6QnkN7enRheymWdBCWxQ==\n-----END PUBLIC KEY-----\n";

const cases = [];
const add = (name, steps, a = anchor()) => cases.push({ name, anchor: a, steps });

add("accept_2_of_3_with_scoped_roles", [step(v1, ok({ version: 1, answers: [true, false, false, true, false, false, false] }), {
  queries: [{ kind: "key", keyid: K.sha256, role: "receipt" }, { kind: "key", keyid: K.sha256, role: "policy-pack" },
    { kind: "key", keyid: OUT.sha256, role: "receipt" }, { kind: "pin", field: "policy_sha256", actual: POLICY },
    { kind: "pin", field: "policy_sha256", actual: "b".repeat(64) }, { kind: "pin", field: "registry_sha256", actual: POLICY },
    { kind: "single_use" }] })]);
add("one_signature_below_threshold", [step(sign(body(), [R[0]]), deny("root_threshold_met", "state_persisted"))]);
add("repeated_signature_counts_once", [step({ ...v1, signatures: [v1.signatures[0], v1.signatures[0]] },
  { trusted: false, reasons: ["root_threshold_met", "state_persisted"] })]);
const withOut = sign(body(), [R[0], OUT]);
add("outsider_signature_not_counted", [step(withOut, { trusted: false, reasons: ["root_threshold_met", "state_persisted"] })]);
add("spoofed_keyid_not_counted", [step({ ...withOut, signatures: [withOut.signatures[0], { ...withOut.signatures[1], keyid: R[1].sha256 }] },
  { trusted: false, reasons: ["root_threshold_met", "state_persisted"] })]);
add("tampered_body_breaks_threshold", [step({ ...v1, signed: { ...v1.signed, trusted_keys: [{ keyid: OUT.sha256, roles: ["receipt"] }] } },
  { trusted: false, reasons: ["root_threshold_met", "state_persisted"] })]);
add("rollback_refused_current_idempotent", [step(v1, ok()), step(v2, ok()), step(v2, ok()),
  step(v1, { trusted: false, reasons: ["not_rolled_back", "state_persisted"] }), step(v3, ok())]);
add("same_version_fork_refused", [step(v1, ok()),
  step(sign(body({ policy_sha256: "c".repeat(64) })), { trusted: false, reasons: ["no_version_fork", "state_persisted"] })]);
add("expired_config", [step(sign(body({ issued_at: "2025-01-01T00:00:00Z", expires_at: "2025-06-01T00:00:00Z" })),
  { trusted: false, reasons: ["not_expired", "state_persisted"] })]);
add("issued_in_future", [step(sign(body({ issued_at: "2098-01-01T00:00:00Z" })),
  { trusted: false, reasons: ["issued_not_in_future", "state_persisted"] })]);
add("caller_time_denies", [step(v1, { trusted: false, reasons: ["caller_time_absent", "state_persisted"] }, { caller_time: "2030-01-01T00:00:00Z" }),
  step(v1, ok())]);
add("clock_behind_persisted_floor", [step(v1, ok()),
  step(v1, { trusted: false, reasons: ["trusted_time", "state_persisted"] }, { before: { kind: "floor_future", version: 1 } })]);
const rotated = body({ version: 2, root: anchor(N) });
add("root_rotation_needs_old_and_new_threshold", [step(v1, ok()),
  step(sign(rotated, [R[0], R[1]]), { trusted: false, reasons: ["new_root_threshold_met", "state_persisted"] }),
  step(sign(rotated, [N[0], N[1]]), { trusted: false, reasons: ["root_threshold_met", "state_persisted"] }),
  step(sign(rotated, [R[0], R[2], N[1], N[2]]), ok()),
  // Rotating back needs the current (new) root: old-root signatures alone are not enough.
  step(sign(body({ version: 3 }), [R[0], R[1]]), { trusted: false, reasons: ["root_threshold_met", "state_persisted"] }),
  step(sign(body({ version: 3, root: anchor(N) }), [N[0], N[2]]), ok())]);
add("revocation_is_sticky", [step(v1, ok()),
  step(sign(body({ version: 2, revoked_keys: [K.sha256] })), ok({ answers: [false] }), { queries: [{ kind: "key", keyid: K.sha256, role: "receipt" }] }),
  step(sign(body({ version: 3 })), ok({ answers: [false, true] }), { queries: [{ kind: "key", keyid: K.sha256, role: "receipt" }, { kind: "key", keyid: P.sha256, role: "policy-pack" }] })]);
add("corrupt_or_unexpected_state_fails_closed", [
  step(v1, { trusted: false, reasons: ["state_readable", ...malformed.reasons] }, { before: { kind: "write_state_file", name: "v000000000009.json", contents: "{not json" } }),
  step(v1, ok(), { before: { kind: "remove_state_file", name: "v000000000009.json" } }),
  step(v1, { trusted: false, reasons: ["state_readable", ...malformed.reasons] }, { before: { kind: "write_state_file", name: "notes.txt", contents: "x" } }),
  step(v1, ok(), { before: { kind: "remove_state_file", name: "notes.txt" } })]);
add("concurrent_newer_version_wins", [step(v2, { trusted: false, reasons: ["not_rolled_back", "state_persisted"] }, { race_envelope: v3 }),
  step(v3, ok()), step(v2, { trusted: false, reasons: ["not_rolled_back", "state_persisted"] })]);
add("require_single_use", [step(sign(body({ require_single_use: true })), ok({ answers: [true] }), { queries: [{ kind: "single_use" }] }),
  // An untrusted decision also "requires" single use (fail closed).
  step(sign(body({ version: 2 }), [R[0]]), { trusted: false, reasons: ["root_threshold_met", "state_persisted"], answers: [true] }, { queries: [{ kind: "single_use" }] })]);
const bad = [
  ["unknown_body_field", { ...body(), extra: 1 }],
  ["threshold_above_keys", body({ root: { threshold: 4, keyids: R.map(r => r.sha256) } })],
  ["unknown_role", body({ trusted_keys: [{ keyid: K.sha256, roles: ["admin"] }] })],
  ["empty_roles", body({ trusted_keys: [{ keyid: K.sha256, roles: [] }] })],
  ["version_zero", body({ version: 0 })],
  ["version_fraction", body({ version: 1.5 })],
  ["version_string", body({ version: "1" })],
  ["february_30", body({ issued_at: "2026-02-30T00:00:00Z" })],
  ["hour_24", body({ issued_at: "2026-01-01T24:00:00Z" })],
  ["pre_1970", body({ issued_at: "1969-12-31T23:59:59Z" })],
  ["offset_time", body({ issued_at: "2026-01-01T00:00:00+00:00" })],
  ["expires_before_issued", body({ expires_at: "2025-12-31T00:00:00Z" })],
  ["single_use_not_boolean", body({ require_single_use: "yes" })],
  ["uppercase_digest", body({ policy_sha256: "A".repeat(64) })],
  ["duplicate_trusted_key", body({ trusted_keys: [{ keyid: K.sha256, roles: ["receipt"] }, { keyid: K.sha256, roles: ["policy-pack"] }] })],
  ["duplicate_root_keyid", body({ root: { threshold: 1, keyids: [R[0].sha256, R[0].sha256] } })]
];
for (const [name, b] of bad) add(`malformed_${name}`, [step(rawSign(b), malformed)]);
add("malformed_envelope_extra_key", [step({ ...v1, note: "x" }, malformed)]);
add("malformed_signatures_not_array", [step({ ...v1, signatures: {} }, malformed)]);
const enc = (name, mutate) => add(`strict_encoding_${name}`, [step({ ...v1, signatures: [mutate(v1.signatures[0]), v1.signatures[1]] },
  { trusted: false, reasons: ["root_threshold_met", "state_persisted"] })]);
enc("signature_trailing_newline", s => ({ ...s, signature_base64: `${s.signature_base64}\n` }));
enc("signature_unpadded", s => ({ ...s, signature_base64: s.signature_base64.replace(/==$/, "") }));
enc("signature_urlsafe", s => ({ ...s, signature_base64: s.signature_base64.replace(/\+/g, "-").replace(/\//g, "_") }));
enc("pem_crlf", s => ({ ...s, public_key_pem: s.public_key_pem.replace(/\n/g, "\r\n") }));
enc("pem_no_armor", s => ({ ...s, public_key_pem: s.public_key_pem.replace(/-----[A-Z ]+-----\n?/g, "") }));
enc("pem_p256_key", s => ({ ...s, public_key_pem: P256_PEM }));
enc("keyid_uppercase", s => ({ ...s, keyid: s.keyid.toUpperCase() }));
const v1Text = JSON.stringify(v1);
add("strict_json_integral_float_version", [{ envelope_text: v1Text.replace('"version":1,', '"version":1.0,'), expect: ok() }]);
add("strict_json_duplicate_key", [{ envelope_text: v1Text.replace('"version":1,', '"version":1,"version":2,'), expect: { parse_error: true } }]);
add("consumption_is_at_most_once", [
  { consume: { parts: ["cli-verifier", "verify-witness", "d".repeat(64)] }, expect: { key: consumptionKey(["cli-verifier", "verify-witness", "d".repeat(64)]), consumed: true } },
  { consume: { parts: ["cli-verifier", "verify-witness", "d".repeat(64)] }, expect: { consumed: false } },
  { consume: { parts: ["cli-verifier", "verify-signed-quorum", "d".repeat(64)] }, expect: { consumed: true } }]);

const vectors = {
  schema: "aml-trust-config-conformance/1",
  note: "Generated by conformance/trust-config/generate.mjs. Synthetic canary keys derived from public labels; no private key is stored. Every implementation must produce `expect` (a subset of its result) and identical full results.",
  cases
};
const file = path.join(here, "vectors.json");
const text = `${JSON.stringify(vectors, null, 1)}\n`;
if (process.argv.includes("--check")) {
  if (fs.readFileSync(file, "utf8") !== text) { console.error("vectors.json is stale: run node conformance/trust-config/generate.mjs"); process.exit(1); }
} else {
  fs.writeFileSync(file, text);
  console.log(`wrote ${cases.length} cases, ${cases.reduce((n, c) => n + c.steps.length, 0)} steps`);
}
